  svg='<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#193a58"/><stop offset="1" stop-color="#5a87a1"/></linearGradient></defs><rect width="1280" height="720" fill="url(#g)"/><circle cx="990" cy="340" r="220" fill="none" stroke="#e4c487" stroke-width="4"/><path d="M880 440v-170l110-65 110 65v170M930 440v-125h120v125" fill="none" stroke="#e4c487" stroke-width="5"/><text x="80" y="170" font-size="28" fill="#f4dfb8" font-family="Arial">NIPPONFERRY · TOKYO</text><text x="80" y="309" font-size="54" fill="white" font-family="sans-serif" font-weight="bold">스가모 지조도리 상점가</text><text x="80" y="378" font-size="31" fill="#f4dfb8" font-family="sans-serif">부모님 동반 도보·참배 가이드</text><text x="80" y="625" font-size="22" fill="white" font-family="sans-serif">자체 제작 정보형 이미지 · 현장 실사진 아님</text></svg>'
